import { Lock, Workflow } from 'lucide-react';
import type { ProjectCaseStudy } from '../../types';

// Projects with a screenshot in public/images/projects (generated by `npm run optimize:images`).
const screenshots = new Set(['gestlife', 'staropub']);

interface ProjectPreviewProps {
  project: ProjectCaseStudy;
  /** Shown instead of a screenshot for projects without a public UI */
  privateNote: string;
  screenshotLabel: string;
  sizes: string;
  className?: string;
}

/** A screenshot in a minimal browser frame, or a branded placeholder for internal systems. */
export const ProjectPreview = ({
  project,
  privateNote,
  screenshotLabel,
  sizes,
  className = '',
}: ProjectPreviewProps) => {
  if (!screenshots.has(project.id)) {
    return (
      <div
        className={`relative flex aspect-[16/10] flex-col items-center justify-center gap-3 overflow-hidden bg-linear-to-br from-slate-900 via-indigo-950 to-emerald-950 text-center ${className}`}
      >
        <div
          aria-hidden="true"
          className="absolute -top-10 -right-10 h-48 w-48 rounded-full bg-emerald-500/20 blur-3xl"
        />
        <Workflow className="relative h-10 w-10 text-emerald-300" aria-hidden="true" />
        <span className="relative inline-flex items-center gap-1.5 rounded-full border border-white/15 bg-white/5 px-3 py-1 text-[11px] font-semibold text-slate-300">
          <Lock className="h-3 w-3" aria-hidden="true" />
          {privateNote}
        </span>
      </div>
    );
  }

  const base = `/images/projects/${project.id}`;
  return (
    <div className={`overflow-hidden bg-slate-200 dark:bg-slate-800 ${className}`}>
      <div aria-hidden="true" className="flex items-center gap-1.5 bg-slate-200 px-3 py-2 dark:bg-slate-800">
        <span className="h-2 w-2 rounded-full bg-rose-400" />
        <span className="h-2 w-2 rounded-full bg-amber-400" />
        <span className="h-2 w-2 rounded-full bg-emerald-400" />
        {project.liveUrl && (
          <span className="ml-2 truncate rounded-md bg-white/70 px-2 py-0.5 text-[10px] text-slate-500 dark:bg-slate-900/70 dark:text-slate-400">
            {project.liveUrl.replace(/^https?:\/\//, '')}
          </span>
        )}
      </div>
      <picture>
        <source type="image/avif" srcSet={`${base}-400.avif 400w, ${base}-800.avif 800w`} sizes={sizes} />
        <source type="image/webp" srcSet={`${base}-400.webp 400w, ${base}-800.webp 800w`} sizes={sizes} />
        <img
          src={`${base}-800.webp`}
          alt={`${project.title} — ${screenshotLabel}`}
          width={800}
          height={500}
          loading="lazy"
          decoding="async"
          className="aspect-[16/10] w-full object-cover object-top transition-transform duration-500 group-hover:scale-[1.03]"
        />
      </picture>
    </div>
  );
};
